<?php declare(strict_types=1);
$root=dirname(__DIR__); $out=$root.'/build'; if(!is_dir($out)) mkdir($out,0700,true); $version='communication-ledger-'.gmdate('YmdHis'); $archive=$out.'/'.$version.'.zip'; $allowed=['public','src','migrations','scripts','README.md']; $required=['public/index.php','public/.htaccess','src/Config/Config.php','migrations/001_initial_schema.sql']; foreach($required as $file) if(!is_file($root.'/'.$file)) throw new RuntimeException('Missing required deployment file.'); if(!class_exists('ZipArchive')) throw new RuntimeException('ZipArchive extension is required.'); $zip=new ZipArchive(); if($zip->open($archive,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true) throw new RuntimeException('Unable to create archive.'); $manifest=[]; foreach($allowed as $item){$path=$root.'/'.$item;if(is_file($path)){$zip->addFile($path,$item);$manifest[$item]=hash_file('sha256',$path);continue;}foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($path,FilesystemIterator::SKIP_DOTS)) as $f){$relative=str_replace(DIRECTORY_SEPARATOR,'/',substr($f->getPathname(),strlen($root)+1)); if(str_starts_with($relative,'public/')) $relative=substr($relative,7); if(preg_match('#(^|/)(tests|build|logs|backups)(/|$)|(^|/)config\.php$|(^|/)\.env$#',$relative))continue;$zip->addFile($f->getPathname(),$relative);$manifest[$relative]=hash_file('sha256',$f->getPathname());}} $zip->addFromString('manifest.json',json_encode(['serviceVersion'=>$version,'files'=>$manifest],JSON_PRETTY_PRINT));$zip->close();echo $archive.PHP_EOL;
